{
  "name": "x-1412526-ai-ci-relationship-auditor",
  "version": "1.0.0",
  "description": "Analyzes ServiceNow Discovery logs using LLM to detect missing CI dependency relationships in the CMDB. Uses IRE validation and a confidence gate to auto-write high-confidence relationships and route low-confidence ones to human review.",
  "license": "UNLICENSED",
  "imports": {
    "#now:*": "./@types/servicenow/fluent/*/index.js"
  },
  "scripts": {
    "build": "now-sdk build",
    "deploy": "now-sdk install",
    "transform": "now-sdk transform",
    "types": "now-sdk dependencies"
  },
  "devDependencies": {
    "@servicenow/sdk": "4.6.0",
    "@servicenow/glide": "27.0.5"
  }
}
